export function searchCompanies(query: string, limit = 8): CompanyItem[] {
  if (!query || !query.trim()) {
    return COMPANIES.slice(0, limit);
  }
  const q = query.toLowerCase().trim();
  return COMPANIES.filter((comp) => {
    if (comp.name.toLowerCase().includes(q)) return true;
    if (comp.domain.toLowerCase().includes(q)) return true;
    if (comp.aliases && comp.aliases.some((a) => a.toLowerCase().includes(q))) return true;
    if (comp.category && comp.category.toLowerCase().includes(q)) return true;
    return false;
  }).slice(0, limit);
}

export function findCompanyByName(name: string): CompanyItem | undefined {
  if (!name) return undefined;
  const lower = name.toLowerCase().trim();
  return COMPANIES.find(
    (c) =>
      c.name.toLowerCase() === lower ||
      c.aliases?.some((a) => a.toLowerCase() === lower) ||
      c.name.toLowerCase().includes(lower) ||
      lower.includes(c.name.toLowerCase())
  );
}
